// Own, isolated Playwright config for the issue #123 generated-starter
// consumption proof. Separate from the root `playwright.config.mjs`
// (port 4173) and from the drawing-companion qualification's own
// config (port 4280). Serves the fixture generated by
// `generate-fixture.mjs` using *its own* `scripts/serve.mjs` -- the
// same static server a real consumer of the generated starter would
// run -- on private port 4282.
import { defineConfig, devices } from "@playwright/test";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { FIXTURE_DEST } from "./generate-fixture.mjs";

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = resolve(here, "..", "..");

const browser = process.env.MINIQUAD_BROWSER;
const known = ["chromium", "firefox", "webkit"];
if (browser && !known.includes(browser)) {
  throw new Error("Invalid MINIQUAD_BROWSER: " + browser);
}
const port = Number(process.env.DRAW_STARTER_CONSUMPTION_PORT || 4282);

export default defineConfig({
  testDir: resolve(repoRoot, "tests/browser"),
  testMatch: "draw-starter-consumption.spec.mjs",
  timeout: 45000,
  expect: { timeout: 20000 },
  retries: 0,
  workers: 1,
  reporter: [["list"]],
  use: {
    baseURL: "http://127.0.0.1:" + port,
    trace: "retain-on-failure",
    screenshot: "only-on-failure",
    headless: process.env.MINIQUAD_HEADFUL !== "1",
  },
  projects: [
    ...known
      .filter((name) => !browser || browser === name)
      .map((name) => ({
        name,
        use: {
          ...devices[name === "chromium" ? "Desktop Chrome" : name === "firefox" ? "Desktop Firefox" : "Desktop Safari"],
          viewport: { width: 800, height: 500 },
          launchOptions:
            name === "chromium"
              ? { args: ["--enable-webgl", "--enable-unsafe-swiftshader", "--use-gl=angle", "--use-angle=swiftshader"] }
              : {},
        },
      })),
  ],
  webServer: {
    command: "node " + resolve(FIXTURE_DEST, "scripts", "serve.mjs") + " --port " + port,
    url: "http://127.0.0.1:" + port + "/",
    reuseExistingServer: false,
    timeout: 20000,
  },
});
